// ── Réinitialisation du mot de passe via notre fonction Vercel (Resend) ──
// Remplace l'ancien sendPasswordResetEmail de Firebase (qui ne délivrait pas les emails)
export async function demanderResetPassword(email: string): Promise<{ok: boolean, error?: string}> {
  try {
    const resp = await fetch('/api/reset-password', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: (email || '').trim().toLowerCase() }),
    });
    if (resp.ok) return { ok: true };
    const data = await resp.json().catch(() => ({}));
    return { ok: false, error: data.error || 'Envoi impossible' };
  } catch (e: any) {
    return { ok: false, error: e?.message || 'Erreur réseau' };
  }
}

// ── Email de notification (prévient même app fermée) via /api/notify (Resend) ──
// Best-effort : si l'envoi échoue, on n'interrompt pas l'action en cours.
export async function envoyerEmailNotif(to: string, sujet: string, message: string): Promise<void> {
  if (!to) return;
  try {
    await fetch('/api/notify', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ to, sujet, message }),
    });
  } catch { /* échec silencieux : la notif Firestore reste la source principale */ }
}

// Écrit une notification ET déclenche un vrai push (même app fermée) — à
// utiliser à la place d'un addDoc direct sur 'notifications' partout où c'est
// possible, pour que la personne soit vraiment alertée.
export async function envoyerNotification(data: { to: string | null | undefined, role?: string, type: string, text: string, [cle: string]: any }): Promise<void> {
  if (!data.to) return; // pas de destinataire connu (ex: email null) — rien à faire
  try {
    await addDoc(collection(db, 'notifications'), { ...data, createdAt: new Date().toISOString(), lu: false });
  } catch (e) { console.error('envoyerNotification (Firestore)', e); }
  // Best-effort, ne bloque jamais l'action principale si le push échoue
  const urlCible = data.qrId
    ? (data.source === 'public' ? `/ecoute/${data.qrId}` : `/fan/${data.qrId}`)
    : (data.role === 'artiste' ? '/artiste' : '/notifications');
  fetch('/api/send-push', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email: data.to, title: 'Doniel Zik', body: data.text,
      url: urlCible,
    }),
  }).catch(() => {});
}

