// Optimisation d'image Cloudinary : ajoute f_auto (format moderne) + q_auto (compression intelligente)
// + largeur max optionnelle. Réduit fortement le poids des images → chargement bien plus rapide.
// Ne touche pas aux URLs non-Cloudinary (blob, autres CDN) ni aux données stockées.
export function optimImg(url: string, largeur?: number): string {
  if (!url || typeof url !== 'string') return url || '';
  if (!url.includes('/upload/')) return url;
  if (url.startsWith('blob:') || url.startsWith('data:')) return url;
  if (url.includes('f_auto') || url.includes('q_auto')) return url;
  const transfo = largeur ? `f_auto,q_auto,w_${largeur},c_limit` : 'f_auto,q_auto';
  return url.replace('/upload/', `/upload/${transfo}/`);
}

// Journal des transactions (audit anti-triche) : trace chaque mouvement de solde
export async function logTx(uid: string, type: string, oscartDelta: number, kiffsDelta: number, raison: string) {
  try {
    await addDoc(collection(db, 'transactions'), {
      uid, type, oscartDelta, kiffsDelta, raison,
      createdAt: new Date().toISOString(),
    });
  } catch (e) { /* silencieux */ }
}

// Lance un paiement GeniusPay (recharge Oscart) : appelle le serveur et redirige vers le checkout.
// Renvoie un message d'erreur si échec, sinon redirige la page.
export async function lancerPaiementGeniusPay(oscart: number, fcfa: number): Promise<string> {
  try {
    const u = auth.currentUser;
    if (!u) return 'Connectez-vous pour recharger.';
    const resp = await fetch('/api/creer-paiement', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ oscart, fcfa, uid: u.uid, email: u.email, nom: u.displayName }),
    });
    const data = await resp.json();
    if (data.ok && data.url) { window.location.href = data.url; return ''; }
    return data.error || 'Erreur, réessayez.';
  } catch { return 'Erreur de connexion, réessayez.'; }
}

// Notifie les autres mélomanes qui ont déjà interagi (commenté/kiffé...) avec un même qrId,
// pour ramener les actifs ("X a fait l'action, toi aussi"). Best-effort, ne bloque jamais.
export async function notifierActiviteCommunaute(qrId: string, exclureUid: string, message: string): Promise<void> {
  if (!qrId) return;
  try {
    // On cible les mélomanes qui ont laissé un commentaire sur ce contenu (preuve d'intérêt)
    const snap = await getDocs(query(collection(db, 'commentaires'), where('qrId','==',qrId)));
    const dejaNotifies = new Set<string>();
    for (const d of snap.docs) {
      const c = d.data();
      const emailCible = c.userEmail;
      if (emailCible && c.userId !== exclureUid && !dejaNotifies.has(emailCible)) {
        dejaNotifies.add(emailCible);
        await envoyerNotification({
          to: emailCible, type: 'activite',
          text: message, qrId, createdAt: new Date().toISOString(),        });
      }
    }
  } catch(e) { console.error('notif activite communaute', e); }
}

// Donner UN kiff (Option A) : dépense le stock du donneur, compte les offerts, crédite l'artiste
export async function donnerKiff(uid: string, qrId: string, artistEmail?: string, source: 'qr' | 'public' = 'qr'): Promise<'ok'|'vide'|'erreur'> {
  try {
    const sSnap = await getDocs(query(collection(db,'coins_solde'), where('uid','==',uid)));
    if (sSnap.empty) return 'vide';
    const sDoc = sSnap.docs[0];
    const dispo = sDoc.data().kiffsDispo || 0;
    if (dispo <= 0) return 'vide';
    await updateDoc(doc(db,'coins_solde',sDoc.id), {
      kiffsDispo: dispo - 1,
      kiffsOfferts: (sDoc.data().kiffsOfferts || 0) + 1,
    });
    await setDoc(doc(db,'kiffs_compteur', qrId), { qrId, artistEmail: artistEmail || '', total: increment(1) }, { merge: true });
    // Signal de recommandation : le fan a kiffé ce contenu — 1 doc par fan+contenu,
    // incrémenté à chaque kiff. Alimente la section « Pour toi » de Découvrir.
    if (uid && qrId) {
      setDoc(doc(db, 'historique_ecoute', `${uid}__${qrId}`), {
        uid, qrId, artistEmail: artistEmail || '', type: 'kiff',
        nb: increment(1), ts: new Date().toISOString(),
      }, { merge: true }).catch(() => {});
    }
    if (artistEmail) {
      await setDoc(doc(db,'kiffs_artiste', artistEmail), { artistEmail, total: increment(1) }, { merge: true });
      // Le Kiff (like gratuit) ne notifiait jamais l'artiste, contrairement aux
      // commentaires — corrigé pour que ce soit cohérent, et envoie maintenant
      // un vrai push (même app fermée).
      await envoyerNotification({
        to: artistEmail, role: 'artiste', type: 'kiff',
        text: `${auth.currentUser?.displayName || 'Un mélomane'} a kiffé votre contenu`,
        qrId, source, from: auth.currentUser?.displayName || 'Un mélomane',
      });
    }
    logTx(uid, 'kiff_donne', 0, -1, 'Kiff offert');
    return 'ok';
  } catch (e) { console.error(e); return 'erreur'; }
}
